import java.io.*;
import java.math.BigInteger;

public class HeightAllTheSame {
    public static void main(String[] args) throws Exception {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        long N = sc.nextLong();
        long M = sc.nextLong();
        long L = sc.nextLong();
        long R = sc.nextLong();

        long mod = 998244353L;
        BigInteger MOD = BigInteger.valueOf(mod);
        long len = R - L + 1;
        long E = len / 2 + (R % 2 == 0 && L % 2 == 0 ? 1 : 0);
        long O = len - E;
        long nm = N * M;
        long ans;

        if (nm % 2 == 1) {
            ans = BigInteger.valueOf(E + O).modPow(BigInteger.valueOf(nm), MOD).longValue();
        } else {
            ans = BigInteger.valueOf(E + O).modPow(BigInteger.valueOf(nm), MOD)
                    .add(BigInteger.valueOf(E - O).modPow(BigInteger.valueOf(nm), MOD))
                    .mod(MOD).longValue();
            ans = ans * BigInteger.valueOf(2).modPow(MOD.subtract(BigInteger.ONE).subtract(BigInteger.ONE), MOD).longValue() % mod;
        }
        out.println(ans);
        out.close();
    }

    static class FastScanner {
        // same as original FastScanner, omitted for brevity (identical)
        public int BS = 1<<16;
        public char NC = (char)0;
        byte[] buf = new byte[BS];
        int bId = 0, size = 0;
        char c = NC;
        double cnt = 1;
        BufferedInputStream in;

        public FastScanner() {
            in = new BufferedInputStream(System.in, BS);
        }

        private char getChar(){
            while(bId==size) {
                try {
                    size = in.read(buf);
                }catch(Exception e) {
                    return NC;
                }
                if(size==-1)return NC;
                bId=0;
            }
            return (char)buf[bId++];
        }

        public long nextLong() {
            cnt=1;
            boolean neg = false;
            if(c==NC)c=getChar();
            for(;(c<'0' || c>'9'); c = getChar()) {
                if(c=='-')neg=true;
            }
            long res = 0;
            for(; c>='0' && c <='9'; c=getChar()) {
                res = (res<<3)+(res<<1)+c-'0';
                cnt*=10;
            }
            return neg?-res:res;
        }
    }
}
